function construct_direct_gsn_endpoint_basis_i_ic_sminus1(lambda, m, nu, omega)
    lambda = ComplexF64(lambda)
    m = Float64(m)
    nu = Float64(nu)
    omega = ComplexF64(omega)
    l2 = lambda * lambda
    m2 = m * m
    m3 = m2 * m
    o2 = omega * omega
    s1 = sin(nu)
    c1 = sqrt((1 - s1) * (1 + s1))
    sn = s1
    c = c1
    cp2 = c * c
    cp3 = cp2 * c
    cp4 = cp3 * c
    cp5 = cp4 * c
    cp6 = cp5 * c
    cp7 = cp6 * c
    cp8 = cp7 * c
    cp9 = cp8 * c
    cp10 = cp9 * c
    cp11 = cp10 * c
    cp12 = cp11 * c
    cp13 = cp12 * c
    cp14 = cp13 * c
    cp15 = cp14 * c
    cp16 = cp15 * c
    coeffs = Vector{ComplexF64}(undef, LEN_DIRECT_GSN_ENDPOINT_i_ic_sminus1)
    _construct_direct_gsn_endpoint_basis_i_ic_sminus1_block_1!(coeffs, lambda, m, nu, omega, l2, m2, m3, o2, s1, c1, sn, c, cp2, cp3, cp4, cp5, cp6, cp7, cp8, cp9, cp10, cp11, cp12, cp13, cp14, cp15, cp16)
    _construct_direct_gsn_endpoint_basis_i_ic_sminus1_block_2!(coeffs, lambda, m, nu, omega, l2, m2, m3, o2, s1, c1, sn, c, cp2, cp3, cp4, cp5, cp6, cp7, cp8, cp9, cp10, cp11, cp12, cp13, cp14, cp15, cp16)
    _construct_direct_gsn_endpoint_basis_i_ic_sminus1_block_3!(coeffs, lambda, m, nu, omega, l2, m2, m3, o2, s1, c1, sn, c, cp2, cp3, cp4, cp5, cp6, cp7, cp8, cp9, cp10, cp11, cp12, cp13, cp14, cp15, cp16)
    _construct_direct_gsn_endpoint_basis_i_ic_sminus1_block_4!(coeffs, lambda, m, nu, omega, l2, m2, m3, o2, s1, c1, sn, c, cp2, cp3, cp4, cp5, cp6, cp7, cp8, cp9, cp10, cp11, cp12, cp13, cp14, cp15, cp16)
    _construct_direct_gsn_endpoint_basis_i_ic_sminus1_block_5!(coeffs, lambda, m, nu, omega, l2, m2, m3, o2, s1, c1, sn, c, cp2, cp3, cp4, cp5, cp6, cp7, cp8, cp9, cp10, cp11, cp12, cp13, cp14, cp15, cp16)
